/* eslint-disable */
// @ts-nocheck — generated from the approved layout catalog (docs/site-builder/redesign-plan.md,
// https://claude.ai/artifact/YZYPWqcrXZF3nBqoAv6ELH). Pure string builders for the layout-card
// thumbnails: each draw() returns SVG markup for a 160×100 viewBox. Colors come from CSS classes
// (.k ink, .m muted, .a accent, .i image, .c card, .d dark, .w on-dark, .t tint) set in wireframes.css.
// To change a thumbnail, edit it here and in the catalog page together.

export interface WireframeLayout { name: string; desc: string; draw: () => string }
export interface WireframeSection { id: string; name: string; blurb: string; layouts: WireframeLayout[] }

/* ── wireframe primitives (viewBox 0 0 160 100) ───────────────────────── */
const R = (x, y, w, h, c = 'm', r = 0) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" class="${c}"/>`;
const H = (x, y, w, s = 4, c = 'k') => R(x, y, w, s, c, s / 3);                       // heading bar
const T = (x, y, w, n = 2, c = 'm', g = 4) => Array.from({ length: n }, (_, i) => R(x, y + i * g, i === n - 1 && n > 1 ? w * .65 : w, 1.8, c, .9)).join(''); // text lines
const B = (x, y, w = 22, h = 7, c = 'a') => R(x, y, w, h, c, 1.6);                     // button
const BO = (x, y, w = 22, h = 7) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="1.6" class="sa"/>`;
const PILL = (x, y, w = 24, h = 7, c = 'a') => R(x, y, w, h, c, h / 2);
const IM = (x, y, w, h, r = 1.5) => R(x, y, w, h, 'i', r) + (w > 10 && h > 8 ? `<circle cx="${x + w * .3}" cy="${y + h * .32}" r="${Math.min(w, h) * .08}" class="gl"/><path d="M${x + w * .12} ${y + h * .86} L${x + w * .42} ${y + h * .5} L${x + w * .6} ${y + h * .7} L${x + w * .72} ${y + h * .58} L${x + w * .9} ${y + h * .86} Z" class="gl"/>` : '');
const CI = (cx, cy, r, c = 'i') => `<circle cx="${cx}" cy="${cy}" r="${r}" class="${c}"/>`;
const AR = (x, y, w, h, c = 'i') => `<path d="M${x} ${y + h} V${y + w / 2} A${w / 2} ${w / 2} 0 0 1 ${x + w} ${y + w / 2} V${y + h} Z" class="${c}"/>`;
const CD = (x, y, w, h, r = 2) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" class="c"/>`;
const LN = (x1, y1, x2, y2, c = 's') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="${c}"/>`;
const DL = (x1, y, x2) => `<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" class="s" stroke-dasharray="1 1.6"/>`;
const STARS = (x, y, n = 5, s = 2.2) => Array.from({ length: n }, (_, i) => `<path d="M${x + i * s * 2.2} ${y - s} L${x + i * s * 2.2 + s * .6} ${y} L${x + i * s * 2.2 - s * .6} ${y} Z" class="a"/><path d="M${x + i * s * 2.2 - s} ${y - s * .35} L${x + i * s * 2.2 + s} ${y - s * .35} L${x + i * s * 2.2} ${y + s * .5} Z" class="a"/>`).join('');
const DOTS = (x, y, n = 3, active = 0) => Array.from({ length: n }, (_, i) => CI(x + i * 4, y, 1.1, i === active ? 'a' : 'm')).join('');
const ICON = (x, y, s = 6, c = 't') => R(x, y, s, s, c, 1.5);
const BG = (c = 'd') => R(0, 0, 160, 100, c);
const TX = (x, y, s, c = 'tx', anchor = 'start') => `<text x="${x}" y="${y}" class="${c}" text-anchor="${anchor}">${s}</text>`;
const QUOTE = (x, y, c = 'a') => `<text x="${x}" y="${y}" class="${c === 'a' ? 'txa' : 'tx'}" style="font-size:16px">“</text>`;
const LOGO = (x, y, c = 'k') => CI(x, y, 2.6, c) + R(x + 4, y - 1.2, 12, 2.4, c, 1.2);
const LINKS = (x, y, n = 4, g = 11, c = 'm') => Array.from({ length: n }, (_, i) => R(x + i * g, y, 7, 1.8, c, .9)).join('');
const GH = (top = 20) => IM(10, top + 8, 140, 100 - top - 16, 2) ; // ghost page below a navbar
const rep = (n, f) => Array.from({ length: n }, (_, i) => f(i)).join('');
const CHECK = (x, y) => `<path d="M${x} ${y} l2 2 l4 -4" class="sa" stroke-linecap="round"/>`;

